/** Change this file (or supply a different file in the research fork) only.
 * Guest mode has no remote access. Online requires your own Firebase deployment.
 * Offline requires a participant-specific offline pack generated by an administrator.
 */
export type DeploymentMode = 'guest' | 'online' | 'offline';
export const deployment: {
  mode: DeploymentMode;
  allowGuest: boolean;
  firebase: null | Record<string, string>;
} = {
  mode: 'guest',
  allowGuest: true,
  firebase: null,
};
